<?php namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\{Desa,TahunAnggaran,DokumenPublikasi}; use App\Services\ApbdesaSummary; use Illuminate\Http\Request;
class SettingController extends Controller { public function dashboard(ApbdesaSummary $summary){$year=TahunAnggaran::aktif()->first();return view('admin.dashboard',['year'=>$year,'desa'=>Desa::first(),'summary'=>$year?$summary->for($year,false):null,'publishedDocuments'=>$year?DokumenPublikasi::publik()->where('tahun_anggaran_id',$year->id)->count():0]);} public function profile(){return view('admin.profile.edit',['desa'=>Desa::firstOrFail()]);} public function updateProfile(Request $r){$data=$r->validate(['nama'=>'required|string|max:255','kecamatan'=>'nullable|string|max:255','kabupaten'=>'required|string|max:255','provinsi'=>'required|string|max:255','alamat'=>'nullable|string','website'=>'nullable|url','email'=>'nullable|email']); Desa::firstOrFail()->update($data); return back()->with('success','Profil desa diperbarui.');} public function years(){return view('admin.years.index',['years'=>TahunAnggaran::orderByDesc('tahun')->get()]);} public function storeYear(Request $r){$d=$r->validate(['tahun'=>'required|integer|min:2000|max:2100|unique:tahun_anggaran,tahun','status'=>'required|in:aktif,nonaktif']); if($d['status']==='aktif') TahunAnggaran::query()->update(['status'=>'nonaktif']); TahunAnggaran::create($d); return back()->with('success','Tahun anggaran ditambahkan.');} public function activate(TahunAnggaran $year){TahunAnggaran::query()->update(['status'=>'nonaktif']);$year->update(['status'=>'aktif']);return back()->with('success','Tahun anggaran aktif diperbarui.');}}
